INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 13, 'theory', 'Quiz: classic design problems');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 0, 'How many combinations does a 7-character base62 key give?', '["About 62 thousand", "About 3.5 trillion", "About 7 million", "About 100 billion"]', 1, '62⁷ ≈ 3.5·10¹² — enough for decades even at hundreds of millions of links per month.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 1, 'What is the difference between 301 and 302 redirects for a shortener?', '["301 is temporary, 302 is permanent", "With 301 the browser remembers it — less load but no click statistics; 302 goes through the service every time", "There is no difference", "301 encrypts the address"]', 1, 'The choice depends on the click analytics requirement.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 2, 'How do you deal with the "hot row" of a view counter?', '["Increase the disk size", "Buffer increments and write them in batches, shard the counter into parts", "Forbid views", "Turn off indexes"]', 1, 'Accumulate in memory and flush every few seconds; a read is the sum of the parts.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 3, 'What does an identifier in the Snowflake scheme consist of?', '["Only random bytes", "Time, node number, and a counter within the millisecond", "A hash of the address", "The user name"]', 1, 'It fits into 8 bytes, is roughly ordered by time, and is generated independently on each node.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 13, 4, 'Why must the check and update in a shared rate limiter be atomic?', '["It makes reading the log faster", "Otherwise parallel requests overtake each other and let through more than the quota", "For encryption", "For compression"]', 1, 'Without atomicity, two simultaneous requests read the same remaining token count.');
